import tomllib
from pathlib import Path

DEFAULTS = {'timeout': 30, 'retries': 3}


def parse_config(path: Path) -> dict:
    raw = path.read_text()
    data = tomllib.loads(raw)
    settings = data['settings']
    return {**DEFAULTS, **settings}

